package com.sami.app.accounting.service;
import com.sami.app.accounting.publicapi.PayablePostingPort; import com.sami.app.common.tenancy.TenantContext; import lombok.RequiredArgsConstructor; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class PayablePostingService implements PayablePostingPort {private final JdbcTemplate jdbc;private final TenantContext tenants;@Override @Transactional public String createPayable(PayableCommand c){Long t=tenants.requireTenantId();return jdbc.query("select id from accounting_payables where tenant_id=? and supplier_invoice_id=?",rs->rs.next()?"PAYABLE-"+rs.getLong(1):null,t,c.supplierInvoiceId())!=null?jdbc.queryForObject("select id from accounting_payables where tenant_id=? and supplier_invoice_id=?",Long.class,t,c.supplierInvoiceId()).toString():insert(c,t); }private String insert(PayableCommand c,Long t){Long id=jdbc.queryForObject("insert into accounting_payables(tenant_id,company_id,branch_id,supplier_id,supplier_invoice_id,idempotency_key,amount,currency) values(?,?,?,?,?,?,?,?) returning id",Long.class,t,c.companyId(),c.branchId(),c.supplierId(),c.supplierInvoiceId(),c.idempotencyKey(),c.amount(),c.currency());return "PAYABLE-"+id;}}
